import assert from 'node:assert/strict';
import {getDocument, OPS} from 'pdfjs-dist/legacy/build/pdf.mjs';

const chunks=[];
for await (const chunk of process.stdin) chunks.push(chunk);
const task=getDocument({data:new Uint8Array(Buffer.concat(chunks)),isEvalSupported:false,useSystemFonts:false,disableFontFace:true});
const pdf=await task.promise;
assert.equal(pdf.numPages,2);
const first=await pdf.getPage(1);
assert.deepEqual(first.view,[0,0,1920,1080]);
const textItems=(await first.getTextContent()).items;
const text=textItems.map(item=>item.str).join(' ');
assert.match(text,/Příliš žluťoučký kůň úpěl ďábelské ódy/);
assert.match(text,/Tržby/);
assert.match(text,/42/);
const one=textItems.find(item=>item.str.trim()==='One');
const two=textItems.find(item=>item.str.trim()==='two');
assert.ok(one&&two,'word-boundary wrap must keep One and two intact');
assert.ok(Math.abs(one.transform[5]-two.transform[5]-24)<0.01,'line height must equal 1.2 times 20');
assert.match((await (await pdf.getPage(2)).getTextContent()).items.map(item=>item.str).join(' '),/Druhá stránka/);
const ops=await first.getOperatorList();
const paths=ops.argsArray.filter((_,i)=>ops.fnArray[i]===OPS.constructPath);
const paintedBoxes=paths.filter(path=>path[0]===OPS.fillStroke||path[0]===OPS.closeFillStroke).map(path=>Array.from(path[2]));
const hasBox=box=>paintedBoxes.some(actual=>actual.every((n,i)=>Math.abs(n-box[i])<0.01));
assert.ok(hasBox([48,838,82,872]),'16-unit rectangle stroke must be inset eight units, without losing half its outline');
assert.ok(hasBox([601,781,1099,879]),'ellipse stroke must fit inside the element frame');
assert.ok(paths.some(path=>path[0]===OPS.stroke&&Array.from(path[2]).every((n,i)=>Math.abs(n-[40.5,606.9,1039.5,679.5][i])<0.01)),'table rows must have natural line-height plus padding, with a full inset border');
assert.ok(ops.fnArray.includes(OPS.constructPath),'actual vector paths');
assert.ok(ops.fnArray.includes(OPS.clip),'frame clipping');
assert.ok(!ops.fnArray.includes(OPS.paintImageXObject),'no raster replacement');
await task.destroy();
